import{_ as e,b as t,c as o,I as r}from"./chunks/framework.C6cPs9Ia.js";const u=JSON.parse('{"title":"开学一个月流水账","description":"高二开学一个月的流水账——课程节奏、课余时间与一些小感想","frontmatter":{"title":"开学一个月流水账","date":"2026-09-13T00:00:00.000Z","tags":["学习","日常","高中"],"cover":"/LQY/images/moment-1.jpg","head":[["meta",{"name":"description","content":"高二开学一个月的流水账——课程节奏、课余时间与一些小感想"}],["meta",{"name":"keywords","content":"高中, 开学, 流水账, 日常"}]]},"headers":[],"relativePath":"posts/high-school-survival.md","filePath":"posts/high-school-survival.md"}'),i={name:"posts/high-school-survival.md"};function l(s,a,n,h,p,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<p>开学一个月了，正好期中前，写篇流水账记录一下现在的状态。</p><hr><h2 id="课程节奏" tabindex="-1">课程节奏 <a class="header-anchor" href="#课程节奏" aria-label="Permalink to &quot;课程节奏&quot;">​</a></h2><p>高二明显比高一紧。数学进度快得像坐高铁，函数刚消化完导数就到了；物理开始上电磁学，公式量翻倍；英语每周听写雷打不动。</p><p>每天的节奏基本是：早读、上课、晚自习、回家。晚自习效率高的晚上回家还能看半小时闲书，效率低的晚上就只剩洗漱睡觉了。</p><h2 id="课余时间" tabindex="-1">课余时间 <a class="header-anchor" href="#课余时间" aria-label="Permalink to &quot;课余时间&quot;">​</a></h2><p>时间紧，但爱好还是要有的，只是学会了用碎片时间：</p><ul><li>课间 10 分钟：刷几道手机里的题，或者看两页漫画</li><li>公交上的 23 分钟：歌单循环（写过了，见另一篇）</li><li>排队打饭 5 分钟：扫一眼更新的情报</li><li>睡前 15 分钟：看一话漫画，绝不多看——多看的下场是凌晨两点</li></ul><p>周五晚上是固定的游戏时间，和同学跑几把 QQ 飞车；周六下午如果没补习，偶尔去看番更新。</p><h2 id="和父母的关系" tabindex="-1">和父母的关系 <a class="header-anchor" href="#和父母的关系" aria-label="Permalink to &quot;和父母的关系&quot;">​</a></h2><p>上学期月考进步了 11 名之后，家里的气氛明显松了不少。我妈现在看到我周末&quot;玩电脑&quot;，只会默默把门带上。</p><p>总结了下经验：不是要和父母斗智斗勇，是<strong>先把该做的做完，再理直气壮地玩</strong>。先交出成绩，再谈自由，这买卖其实挺公平。</p><h2 id="一些小感想" tabindex="-1">一些小感想 <a class="header-anchor" href="#一些小感想" aria-label="Permalink to &quot;一些小感想&quot;">​</a></h2><p>开学前立的 flag：物理上 90、数学稳住、博客月更。目前进度：物理刚过线、数学有点悬、博客达标。</p><p>不算好，但也不算糟。高二是场长跑，比的是谁状态稳，不是谁九月冲得猛。</p><p>十月期中，考完再来汇报。</p>',16)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
